#!/usr/bin/env bash
# Analyse des parcours par le vérificateur de types (méthodes d'objets, adaptateurs, SQL direct)
# et « Le chemin dans le code » : la piste de chaque effet, de la procédure jusqu'à la base.
# Prérequis : apply-carte-membres.sh.
# Usage (racine du repo) : bash apply-pistes-code.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/docs/entities/EntityExplorer.tsx" 2>/dev/null | grep -qF "function CodeTrail"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Le membre se connecte pour la première fois" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-carte-membres.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/src/features/docs/entities/EntityExplorer.tsx" "apps/web/src/features/docs/entities/stories.ts" "scripts/build-procedure-map.mjs" "apps/web/src/features/docs/entities/procedureMap.generated.json")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "function CodeTrail" "apps/web/src/features/docs/entities/EntityExplorer.tsx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/entities"
base64 -d > "apps/web/src/features/docs/entities/procedureMap.generated.json" <<'B64'
